-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.admin_delete_challenge(target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t_title text;
begin
  if not public.is_admin() then raise exception 'Admins only'; end if;
  select title into t_title from public.challenges where id = target;
  if t_title is null then raise exception 'Challenge not found'; end if;
  insert into public.admin_audit_log (actor_id, actor_name, action, target_id, target_name)
  select auth.uid(), (select name from public.profiles where id = auth.uid()),
         'Deleted challenge', target, t_title;
  -- FK cascades handle submissions / results / reminders; rewards.challenge_id is set null.
  delete from public.challenges where id = target;
end; $function$;
